public class TraceMeasurements {
    public static void main(String[] args) {
        int total = 0;
        int count = 0;
        for (int value : new int[] {3, 4, 0, 9}) {
            if (value == 0) {
                break;
            }
            total += value;
            count++;
        }
        if (count > 0) {
            System.out.println("Mean: " + (double) total / count);
        } else {
            System.out.println("No measurements");
        }

        for (int row = 1; row <= 2; row++) {
            for (int column = 1; column <= 3; column++) {
                System.out.print(row == column ? "X" : ".");
            }
            System.out.println();
        }
    }
}

