abstract class Notice {
    private final String label;
    private static int created = 0;

    Notice(String label) {
        this.label = label;
        created++;
    }

    public String heading() { return label; }
    public static int count() { return created; }
    public abstract String message();
}

class Reminder extends Notice {
    Reminder(String label) {
        super(label);
    }

    @Override
    public String message() {
        return heading() + ": review";
    }
}

public class NoticeDemo {
    public static void main(String[] args) {
        Notice first = new Reminder("Loops");
        Notice second = new Reminder("Text");
        System.out.println(first.message());
        System.out.println(second.message());
        System.out.println("Created: " + Notice.count());
    }
}

import java.awt.BorderLayout;
import java.awt.GridLayout;
import javax.swing.*;

public class ReadingWindow {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame frame = new JFrame("Reading planner");
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.setLayout(new BorderLayout(8, 8));

            JPanel form = new JPanel(new GridLayout(2, 2, 6, 6));
            form.add(new JLabel("Topic:"));
            form.add(new JComboBox<String>(
                new String[] {"Loops", "Objects"}));
            form.add(new JLabel("Minutes:"));
            form.add(new JTextField("12", 6));

            frame.add(new JLabel("Choose your next reading"), BorderLayout.NORTH);
            frame.add(form, BorderLayout.CENTER);
            frame.add(new JButton("Plan"), BorderLayout.SOUTH);
            frame.pack();
            frame.setVisible(true);
        });
    }
}

import java.awt.FlowLayout;
import javax.swing.*;

public class ReadingAction {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame frame = new JFrame("Plan a review");
            JTextField minutesField = new JTextField("12", 6);
            JButton plan = new JButton("Plan");
            JLabel status = new JLabel("Enter whole minutes.");

            plan.addActionListener(event -> {
                try {
                    int minutes = Integer.parseInt(minutesField.getText().trim());
                    if (minutes <= 0) {
                        status.setText("Use a positive number.");
                    } else {
                        status.setText("Next review: " + minutes + " min.");
                    }
                } catch (NumberFormatException error) {
                    status.setText("Use whole numbers.");
                }
                frame.pack();
            });

            frame.setLayout(new FlowLayout());
            frame.add(minutesField);
            frame.add(plan);
            frame.add(status);
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.pack();
            frame.setVisible(true);
        });
    }
}
